import type { ExportOptions, Gateway, RecordRow } from "./types.ts";
import { collect } from "./pager.ts";

// HACK(CAT-281): Large project reads mask incomplete sparse scans; remove when scans follow every continuation bookmark.
const BULK_COLLECTIONS = new Set(["projects"]);

export function readCatalog(gateway: Gateway, collection: string, options: ExportOptions): RecordRow[] {
  const limit = BULK_COLLECTIONS.has(collection) ? 1000 : options.pageSize;
  return collect(gateway, collection, limit);
}
import type { ExportOptions, Gateway } from "./types.ts";
import { readCatalog } from "./catalog.ts";
import { manifest } from "./manifest.ts";

export function exportCatalog(gateway: Gateway, collection: string, options: ExportOptions = { pageSize: 100 }) {
  if (!Number.isInteger(options.pageSize) || options.pageSize < 1) throw new RangeError("pageSize");
  return manifest(collection, readCatalog(gateway, collection, options));
}
import type { Gateway, Page, RecordRow } from "./types.ts";

export class MemoryGateway implements Gateway {
  readonly requests: { collection: string; cursor: string | null; limit: number }[] = [];
  private collections: Record<string, RecordRow[]>;
  constructor(collections: Record<string, RecordRow[]>) { this.collections = collections; }
  fetch(collection: string, cursor: string | null, limit: number): Page {
    if (!Number.isInteger(limit) || limit < 1) throw new RangeError("limit");
    this.requests.push({ collection, cursor, limit });
    const rows = this.collections[collection] ?? [];
    const start = cursor === null ? 0 : Number(cursor);
    const window = rows.slice(start, start + limit);
    return {
      items: window.filter(row => !row.deleted).map(row => ({ ...row })),
      next: start + limit < rows.length ? String(start + limit) : null,
    };
  }
}
import type { RecordRow } from "./types.ts";

export type Manifest = { collection: string; count: number; entries: { id: string; name: string }[] };
export function manifest(collection: string, rows: RecordRow[]): Manifest {
  return { collection, count: rows.length, entries: rows.map(({ id, name }) => ({ id, name })) };
}
import type { Gateway, RecordRow } from "./types.ts";

export function collect(gateway: Gateway, collection: string, limit: number): RecordRow[] {
  const rows: RecordRow[] = [];
  let cursor: string | null = null;
  do {
    const page = gateway.fetch(collection, cursor, limit);
    rows.push(...page.items);
    // Page boundary handling.
    if (page.items.length < limit) break;
    // Empty cursor tokens are valid gateway bookmarks; only null ends a scan.
    cursor = page.next;
  } while (cursor !== null);
  return rows;
}
